PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS rooms(id TEXT PRIMARY KEY,number TEXT UNIQUE NOT NULL,category TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 4),rate INTEGER NOT NULL CHECK(rate>0),operational TEXT NOT NULL DEFAULT 'ready' CHECK(operational IN('ready','cleaning','occupied','maintenance')));
CREATE TABLE IF NOT EXISTS bookings(reference TEXT PRIMARY KEY,idempotency_key TEXT UNIQUE NOT NULL,payload_hash TEXT NOT NULL,arrival TEXT NOT NULL,departure TEXT NOT NULL,adults INTEGER NOT NULL,children INTEGER NOT NULL,room_count INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,requests TEXT NOT NULL,extras TEXT NOT NULL,pricing TEXT NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',payment_status TEXT NOT NULL DEFAULT 'demo-paid',checkin_status TEXT NOT NULL DEFAULT 'not-arrived',version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(departure>arrival));
CREATE TABLE IF NOT EXISTS booked_rooms(reference TEXT NOT NULL REFERENCES bookings(reference),room_id TEXT NOT NULL REFERENCES rooms(id),adults INTEGER NOT NULL,children INTEGER NOT NULL,PRIMARY KEY(reference,room_id));
CREATE TRIGGER IF NOT EXISTS prevent_overlap BEFORE INSERT ON booked_rooms BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM booked_rooms existing JOIN bookings old ON old.reference=existing.reference JOIN bookings incoming ON incoming.reference=NEW.reference WHERE existing.room_id=NEW.room_id AND old.reference<>incoming.reference AND old.status='confirmed' AND incoming.status='confirmed' AND old.arrival<incoming.departure AND old.departure>incoming.arrival) THEN RAISE(ABORT,'Room is already reserved for those dates') END; END;
CREATE TABLE IF NOT EXISTS availability_blocks(id TEXT PRIMARY KEY,room_id TEXT NOT NULL REFERENCES rooms(id),arrival TEXT NOT NULL,departure TEXT NOT NULL,reason TEXT NOT NULL,CHECK(departure>arrival));
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,kind TEXT NOT NULL,subject TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0,role TEXT,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lookup_tokens(hash TEXT PRIMARY KEY,email TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS itineraries(reference TEXT PRIMARY KEY REFERENCES bookings(reference),content TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS email_attempts(id TEXT PRIMARY KEY,reference TEXT NOT NULL REFERENCES bookings(reference),version INTEGER NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',provider_id TEXT,error TEXT,html TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,claimed_at INTEGER NOT NULL DEFAULT 0,UNIQUE(reference,version,kind));
CREATE TABLE IF NOT EXISTS staff(username TEXT PRIMARY KEY,salt TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('manager','staff')));
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS prevent_room_overcapacity BEFORE INSERT ON booked_rooms BEGIN SELECT CASE WHEN NEW.adults<1 OR NEW.children<0 OR NEW.adults+NEW.children>(SELECT capacity FROM rooms WHERE id=NEW.room_id) THEN RAISE(ABORT,'Invalid room occupancy') END; END;
CREATE TRIGGER IF NOT EXISTS prevent_block_conflict BEFORE INSERT ON booked_rooms BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM availability_blocks block JOIN bookings booking ON booking.reference=NEW.reference WHERE block.room_id=NEW.room_id AND block.arrival<booking.departure AND block.departure>booking.arrival) THEN RAISE(ABORT,'Room is blocked for those dates') END; END;
CREATE TRIGGER IF NOT EXISTS protect_date_update BEFORE UPDATE OF arrival,departure ON bookings BEGIN SELECT CASE WHEN NEW.status='confirmed' AND EXISTS(SELECT 1 FROM booked_rooms ours JOIN booked_rooms theirs ON ours.room_id=theirs.room_id JOIN bookings other ON other.reference=theirs.reference WHERE ours.reference=NEW.reference AND theirs.reference<>NEW.reference AND other.status='confirmed' AND other.arrival<NEW.departure AND other.departure>NEW.arrival) THEN RAISE(ABORT,'Room is already reserved for those dates') END; END;

CREATE TABLE IF NOT EXISTS guests(email TEXT PRIMARY KEY,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS payment_records(id TEXT PRIMARY KEY,reference TEXT NOT NULL REFERENCES bookings(reference),status TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE TABLE IF NOT EXISTS email_webhook_events(id TEXT PRIMARY KEY,type TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,tier TEXT NOT NULL,capacity INTEGER NOT NULL,inventory INTEGER NOT NULL,rate INTEGER NOT NULL,size INTEGER NOT NULL,view TEXT NOT NULL,description TEXT NOT NULL,photo TEXT NOT NULL,amenities TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS extras(id TEXT PRIMARY KEY,name TEXT NOT NULL,price INTEGER NOT NULL,status TEXT NOT NULL,unit TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS protect_block_insert BEFORE INSERT ON availability_blocks BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM booked_rooms slot JOIN bookings stay ON slot.reference=stay.reference WHERE slot.room_id=NEW.room_id AND stay.status='confirmed' AND stay.arrival<NEW.departure AND stay.departure>NEW.arrival) THEN RAISE(ABORT,'Availability block overlaps a confirmed reservation') END; END;
CREATE TABLE IF NOT EXISTS invites(id TEXT PRIMARY KEY,token_hash TEXT UNIQUE NOT NULL,hint TEXT NOT NULL,label TEXT NOT NULL DEFAULT '',campaign TEXT NOT NULL,nights INTEGER NOT NULL DEFAULT 3,expires_at INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,reference TEXT UNIQUE REFERENCES bookings(reference),redeemed_at TEXT);
